window.products.push({"id":1173348,"name":"Withings Scanwatch - Hybrid Smartwatch & Activity Tracker with Connected GPS, Heart Rate Monitor, Sleep Monitor, Smart Notifications, Water Resistant ","category":"electronics","retail price":299.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/61W7qCBlDVL._AC_SL1500_.jpg","description":"ScanWatch is the first hybrid smartwatch to scan vital parameters to detect heart health conditions and help improve overall fitness. ScanWatch boasts a medical-grade ECG, an oximeter for SpO2 measures, and an exceptional battery life of up to 30 days. Technologies: an electrocardiogram and an oximeter to provide on-demand essential vital parameters.","images":["https://m.media-amazon.com/images/I/61W7qCBlDVL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Withings","source_asin":"B096MFS66S","category_path":"Electronics"},"sku":"BM-1173348","productType":"Electronics","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B096MFS66S","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"electronics-range.jsonl","source_asin":"B096MFS66S","price_pending":true,"merchant_ready":false});
